#!/usr/bin/env python3
from __future__ import annotations
import argparse,hashlib,importlib.util,json,math,pickle
from pathlib import Path
from typing import Any
YEARS=(2023,2025); BLIND_LOW=20.0; BLIND_HIGH=55.0; BINS=('4-9','10-24','25-49','50-99','100+')
ELIGIBLE='P2 matched-literature pretruth panel checkpoint'; INELIGIBLE='P2_MATCHED_INPUT_INELIGIBLE'; P2_SOURCE_SHA256='f19500f6b0dfe481d845af57f3b4d7ec35e678e2191388b7ff4611f8fb2c4eeb'; DSH_SOURCE_SHA256='85cd11afbdebc4a0315ebf1daf42d10d4993d7ab088dd05301e3234b18340a5a'
def require(ok:bool,message:str)->None:
    if not ok: raise RuntimeError(message)
def load_module(path:Path,name:str)->Any:
    spec=importlib.util.spec_from_file_location(name,path); require(spec is not None and spec.loader is not None,f'cannot import {path}'); m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m); return m
def load_checkpoint(path:Path,panel:str)->dict[str,Any]:
    raw=path.read_bytes(); side=path.with_suffix(path.suffix+'.sha256'); require(side.exists() and side.read_text().strip()==hashlib.sha256(raw).hexdigest(),f'checkpoint SHA mismatch {panel}'); o=pickle.loads(raw); require(o['classification'] in {ELIGIBLE,INELIGIBLE},f'wrong checkpoint class {panel}'); require(o['panel']==panel and o['years']==list(YEARS) and o['blind_exclusion']==[BLIND_LOW,BLIND_HIGH],f'checkpoint universe changed {panel}'); require(o['competitor_cluster_values_accessed'] is False and o['known_shower_truth_accessed'] is False,f'labels entered pretruth {panel}')
    if o['classification']==ELIGIBLE:
        require(o['p2_source_sha256']==P2_SOURCE_SHA256 and o['dsh_source_sha256']==DSH_SOURCE_SHA256,f'P2 source identity changed {panel}'); require(o['model_membership_and_rank_frozen_before_truth'] is True,f'freeze flag missing {panel}'); require(len(o['p2_model_pretruth_sha256'])==64 and len(o['p2_membership_pretruth_sha256'])==64 and len(o['v8_order_pretruth_sha256'])==64,f'pretruth hash missing {panel}'); require(hashlib.sha256(json.dumps(o['p2_model_pretruth'],sort_keys=True,separators=(',',':'),allow_nan=False).encode()).hexdigest()==o['p2_model_pretruth_sha256'],f'model hash changed {panel}'); require(hashlib.sha256(json.dumps(o['p2_expanded_families'],sort_keys=True,separators=(',',':'),allow_nan=False).encode()).hexdigest()==o['p2_membership_pretruth_sha256'],f'membership hash changed {panel}'); require(hashlib.sha256(json.dumps(o['v8_multiplicity_order'],separators=(',',':')).encode()).hexdigest()==o['v8_order_pretruth_sha256'],f'order hash changed {panel}')
    else:
        require(o['p2_membership_executed'] is False and o['no_support_or_background_relaxation'] is True,f'ineligible P2 panel mutated {panel}')
